import { useState, useEffect } from 'react';
import api from '../utils/api';
import { Plus, Trash, Edit, Save, X } from 'lucide-react';

// Common preset scopes
const PRESET_SCOPES = ['ALL', 'JCETI', 'GLOBAL', 'SG', 'ISRAEL', 'JAPAN'];

interface Dataset {
    _id: string;
    name: string;
    content: string;
    scope: string; // Now accepts any string for custom companies
    category?: 'company' | 'faq' | 'promotion' | 'other';
    isActive: boolean;
}

export default function Datasets() {
    const [datasets, setDatasets] = useState<Dataset[]>([]);
    const [isEditing, setIsEditing] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState<Partial<Dataset>>({ name: '', content: '', scope: 'ALL', category: 'company', isActive: true });
    const [useCustomScope, setUseCustomScope] = useState(false);
    const [customScope, setCustomScope] = useState('');

    useEffect(() => {
        fetchDatasets();
    }, []);

    const fetchDatasets = async () => {
        const res = await api.get('/datasets');
        setDatasets(res.data);
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('Are you sure?')) {
            await api.delete(`/datasets/${id}`);
            fetchDatasets();
        }
    };

    const handleEdit = (ds: Dataset) => {
        setFormData(ds);
        setEditingId(ds._id);
        // Check if scope is a custom one
        const isCustom = !PRESET_SCOPES.includes(ds.scope);
        setUseCustomScope(isCustom);
        setCustomScope(isCustom ? ds.scope : '');
        setIsEditing(true);
    };

    const handleCreate = () => {
        setFormData({ name: '', content: '', scope: 'ALL', category: 'company', isActive: true });
        setEditingId(null);
        setUseCustomScope(false);
        setCustomScope('');
        setIsEditing(true);
    };

    const handleSave = async () => {
        try {
            const dataToSave = {
                ...formData,
                scope: useCustomScope ? customScope.toUpperCase() : formData.scope
            };
            if (editingId) {
                await api.put(`/datasets/${editingId}`, dataToSave);
            } else {
                await api.post('/datasets', dataToSave);
            }
            setIsEditing(false);
            fetchDatasets();
        } catch (err: any) {
            alert('Error saving: ' + err.message);
        }
    };

    if (isEditing) {
        return (
            <div className="bg-white p-6 rounded-xl shadow-md">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-xl font-semibold">{editingId ? 'Edit Dataset' : 'New Dataset'}</h2>
                    <button onClick={() => setIsEditing(false)} className="text-gray-500 hover:text-gray-700">
                        <X className="h-6 w-6" />
                    </button>
                </div>

                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Name</label>
                        <input
                            className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                            value={formData.name}
                            onChange={e => setFormData({ ...formData, name: e.target.value })}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Scope (Company/Region)</label>
                        <div className="flex items-center gap-4 mt-1">
                            <label className="inline-flex items-center">
                                <input
                                    type="radio"
                                    checked={!useCustomScope}
                                    onChange={() => setUseCustomScope(false)}
                                    className="form-radio"
                                />
                                <span className="ml-2 text-sm">Preset</span>
                            </label>
                            <label className="inline-flex items-center">
                                <input
                                    type="radio"
                                    checked={useCustomScope}
                                    onChange={() => setUseCustomScope(true)}
                                    className="form-radio"
                                />
                                <span className="ml-2 text-sm">New Company</span>
                            </label>
                        </div>
                        {!useCustomScope ? (
                            <select
                                className="mt-2 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                                value={formData.scope}
                                onChange={e => setFormData({ ...formData, scope: e.target.value })}
                            >
                                <option value="ALL">ALL (Global Knowledge)</option>
                                <option value="JCETI">JCETI (Training Institute)</option>
                                <option value="GLOBAL">GLOBAL (Workforce Recruitment)</option>
                                <option value="SG">SG (Singapore)</option>
                                <option value="ISRAEL">ISRAEL</option>
                                <option value="JAPAN">JAPAN</option>
                            </select>
                        ) : (
                            <input
                                className="mt-2 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                                placeholder="Enter new company name (e.g., KOREA, UAE, QATAR)"
                                value={customScope}
                                onChange={e => setCustomScope(e.target.value)}
                            />
                        )}
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Category</label>
                        <select
                            className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                            value={formData.category || 'company'}
                            // @ts-ignore
                            onChange={e => setFormData({ ...formData, category: e.target.value })}
                        >
                            <option value="company">Company Info</option>
                            <option value="faq">FAQ</option>
                            <option value="promotion">Promotions</option>
                            <option value="other">Other</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Content</label>
                        <textarea
                            rows={15}
                            placeholder="Enter company info, FAQs, or other knowledge the chatbot should use..."
                            className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 font-mono text-sm"
                            value={formData.content}
                            onChange={e => setFormData({ ...formData, content: e.target.value })}
                        />
                    </div>

                    <div className="flex justify-end pt-4">
                        <button onClick={() => setIsEditing(false)} className="mr-3 px-4 py-2 text-gray-700 hover:bg-gray-100 rounded">Cancel</button>
                        <button onClick={handleSave} className="flex items-center px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                            <Save className="h-4 w-4 mr-2" /> Save
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold">Datasets</h1>
                <button
                    onClick={handleCreate}
                    className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
                >
                    <Plus className="h-5 w-5 mr-2" /> Add New
                </button>
            </div>

            <div className="bg-white rounded-xl shadow-md overflow-hidden">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Name</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Scope</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Category</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Active</th>
                            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {datasets.map(ds => (
                            <tr key={ds._id} className="hover:bg-gray-50">
                                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{ds.name}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800">
                                        {ds.scope}
                                    </span>
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-purple-100 text-purple-800 capitalize">
                                        {ds.category || 'company'}
                                    </span>
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{ds.isActive ? '✅' : '❌'}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                    <button onClick={() => handleEdit(ds)} className="text-indigo-600 hover:text-indigo-900 mr-4">
                                        <Edit className="h-4 w-4" />
                                    </button>
                                    <button onClick={() => handleDelete(ds._id)} className="text-red-600 hover:text-red-900">
                                        <Trash className="h-4 w-4" />
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {datasets.length === 0 && (
                    <div className="p-8 text-center text-gray-500">No datasets found. Create one to get started.</div>
                )}
            </div>
        </div>
    );
}

import { useState, useEffect, type FormEvent } from 'react';
import { useAuth } from '../context/AuthContext';
import { api } from '../config';
import { useNavigate } from 'react-router-dom';

export default function Login() {
    const { login, token } = useAuth();
    const navigate = useNavigate();
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [needsSetup, setNeedsSetup] = useState(false);

    useEffect(() => {
        if (token) navigate('/dashboard');

        // Check if setup is needed
        api.get('/api/auth/setup-check').then(res => {
            if (res.data.needsSetup) setNeedsSetup(true);
        });
    }, [token, navigate]);

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        try {
            if (needsSetup) {
                await api.post('/api/auth/setup', { username, password });
                // Then login
                const res = await api.post('/api/auth/login', { username, password });
                login(res.data.token);
            } else {
                const res = await api.post('/api/auth/login', { username, password });
                login(res.data.token);
            }
        } catch (err: any) {
            setError(err.response?.data?.message || 'Login failed');
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100">
            <div className="px-8 py-6 mt-4 text-left bg-white shadow-lg rounded-xl w-96">
                <h3 className="text-2xl font-bold text-center text-gray-700">
                    {needsSetup ? 'Admin Setup' : 'Admin Login'}
                </h3>
                {error && <p className="text-red-500 text-sm mt-2">{error}</p>}
                <form onSubmit={handleSubmit} className="mt-4">
                    <div className="mt-4">
                        <label className="block text-sm font-light">Username</label>
                        <input
                            type="text"
                            className="w-full px-4 py-2 mt-2 border rounded-md focus:outline-none focus:ring-1 focus:ring-blue-600"
                            value={username} onChange={e => setUsername(e.target.value)} required
                        />
                    </div>
                    <div className="mt-4">
                        <label className="block text-sm font-light">Password</label>
                        <input
                            type="password"
                            className="w-full px-4 py-2 mt-2 border rounded-md focus:outline-none focus:ring-1 focus:ring-blue-600"
                            value={password} onChange={e => setPassword(e.target.value)} required
                        />
                    </div>
                    <div className="mt-6">
                        <button className="w-full px-6 py-2 text-white bg-blue-600 rounded-lg hover:bg-blue-900">
                            {needsSetup ? 'Create Admin' : 'Login'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { api } from '../config';
import { Smartphone, Plus, Trash, Wifi, WifiOff, Loader } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';

interface Session {
    sessionId: string;
    sessionName: string;
    status: 'connecting' | 'connected' | 'disconnected' | 'scan_qr' | 'reconnecting';
    qr?: string;
    phoneNumber?: string;
    updatedAt: string;
}

export default function Sessions() {
    const [sessions, setSessions] = useState<Session[]>([]);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);

    const fetchSessions = async () => {
        try {
            const res = await api.get('/api/sessions');
            setSessions(res.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch sessions', error);
        }
    };

    useEffect(() => {
        fetchSessions();
        // Poll for status updates (QR codes change often)
        const interval = setInterval(fetchSessions, 3000);
        return () => clearInterval(interval);
    }, []);

    const handleCreateSession = async () => {
        const name = prompt("Enter a name for this device (e.g. 'Support 1'):");
        if (!name) return;

        setCreating(true);
        try {
            await api.post('/api/sessions', { sessionName: name });
            await fetchSessions();
        } catch (error) {
            alert('Failed to create session');
        } finally {
            setCreating(false);
        }
    };

    const handleDeleteSession = async (id: string, name: string) => {
        if (!confirm(`Are you sure you want to remove '${name}'? This will disconnect the device.`)) return;
        try {
            await api.delete(`/api/sessions/${id}`);
            fetchSessions();
        } catch (error) {
            alert('Failed to delete session');
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'connected': return 'text-green-600 bg-green-50 border-green-200';
            case 'scan_qr': return 'text-amber-600 bg-amber-50 border-amber-200';
            case 'disconnected': return 'text-red-600 bg-red-50 border-red-200';
            default: return 'text-blue-600 bg-blue-50 border-blue-200';
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'connected': return <Wifi className="w-5 h-5" />;
            case 'disconnected': return <WifiOff className="w-5 h-5" />;
            case 'scan_qr': return <Smartphone className="w-5 h-5" />;
            default: return <Loader className="w-5 h-5 animate-spin" />;
        }
    };

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">Linked Devices</h1>
                    <p className="text-gray-500 mt-1">Manage multiple WhatsApp accounts connected to this bot.</p>
                </div>
                <button
                    onClick={handleCreateSession}
                    disabled={creating}
                    className="flex items-center px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition disabled:opacity-50"
                >
                    {creating ? <Loader className="animate-spin w-5 h-5 mr-2" /> : <Plus className="w-5 h-5 mr-2" />}
                    Add New Device
                </button>
            </div>

            {loading && sessions.length === 0 ? (
                <div className="text-center py-20 text-gray-500">Loading devices...</div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {sessions.map(session => (
                        <div key={session.sessionId} className={`bg-white rounded-xl shadow-sm border-2 overflow-hidden ${session.status === 'connected' ? 'border-green-100' : 'border-gray-100'}`}>
                            {/* Header */}
                            <div className="p-4 border-b border-gray-100 flex justify-between items-start bg-gray-50/50">
                                <div>
                                    <h3 className="font-bold text-lg text-gray-800">{session.sessionName || session.sessionId}</h3>
                                    <p className="text-xs text-gray-400 font-mono mt-1">{session.sessionId}</p>
                                </div>
                                <button
                                    onClick={() => handleDeleteSession(session.sessionId, session.sessionName)}
                                    className="p-2 text-gray-400 hover:text-red-500 transition rounded-full hover:bg-red-50"
                                    title="Disconnect & Remove"
                                >
                                    <Trash className="w-4 h-4" />
                                </button>
                            </div>

                            {/* Body */}
                            <div className="p-6 flex flex-col items-center justify-center min-h-[200px]">
                                <div className={`flex items-center space-x-2 px-3 py-1 rounded-full text-sm font-medium mb-4 ${getStatusColor(session.status)}`}>
                                    {getStatusIcon(session.status)}
                                    <span className="capitalize">{session.status.replace('_', ' ')}</span>
                                </div>

                                {session.status === 'scan_qr' && session.qr ? (
                                    <div className="flex flex-col items-center animate-in fade-in duration-500">
                                        <div className="bg-white p-2 rounded-lg border shadow-sm">
                                            <QRCodeSVG value={session.qr} size={180} />
                                        </div>
                                        <p className="text-xs text-gray-500 mt-3 text-center">Open WhatsApp → Settings → Linked Devices → Link a Device</p>
                                    </div>
                                ) : session.status === 'connected' ? (
                                    <div className="text-center">
                                        <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-3">
                                            <Wifi className="w-8 h-8" />
                                        </div>
                                        <p className="text-gray-600 font-medium">Device is Online</p>
                                        {session.phoneNumber && <p className="text-sm text-gray-500 mt-1">{session.phoneNumber}</p>}
                                    </div>
                                ) : (
                                    <div className="text-center text-gray-400">
                                        {session.status === 'connecting' ? 'Initializing...' : 'Waiting for status...'}
                                    </div>
                                )}
                            </div>

                            {/* Footer */}
                            <div className="bg-gray-50 px-4 py-2 text-xs text-gray-400 text-center border-t border-gray-100">
                                Last updated: {new Date(session.updatedAt).toLocaleTimeString()}
                            </div>
                        </div>
                    ))}

                    {/* Empty State Card */}
                    {sessions.length === 0 && (
                        <div className="border-2 border-dashed border-gray-300 rounded-xl p-6 flex flex-col items-center justify-center text-gray-400 min-h-[300px]">
                            <Smartphone className="w-12 h-12 mb-3 opacity-20" />
                            <p>No devices connected.</p>
                            <button onClick={handleCreateSession} className="mt-4 text-blue-600 font-medium hover:underline">
                                Link your first device
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}
